CREATE OR REPLACE DYNAMIC TABLE AGG.AGG_FIELD_SERVICE_MONTH_VISIT_TYPE_OUTCOME
  TARGET_LAG = '24 hours'
  WAREHOUSE  = WH_SEMANTIC_REFRESH
  COMMENT = 'Demand-driven aggregate of FCT_FIELD_SERVICE at grain Date.FiscalYear, Date.MonthName, Date.Quarter, FieldService.Outcome, FieldService.VisitType, Date.MonthNumber; covers 32.95% of weighted demand (1 clusters); est. 6,000 rows; ~0.0167 credits/day'
AS
SELECT d1.FISCAL_YEAR,
       d1.MONTH_NAME,
       d1.QUARTER,
       f.OUTCOME,
       f.VISIT_TYPE,
       d1.MONTH_NUMBER,
       SUM(f.DURATION) AS DURATION,
       COUNT(*) AS FIELD_SERVICE_COUNT
FROM CORE.FCT_FIELD_SERVICE f
JOIN CORE.DIM_DATE d1 ON f.DATE_KEY = d1.DATE_KEY
GROUP BY ALL;
